MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
def w3(n):
    h = n // 100
    t = (n % 100) // 10
    o = n % 10
    s = []
    if h:
        s.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        s.append(TENS[t])
    if o:
        s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q = n // val
        if q:
            if val == 1000 and q == 1:
                parts.append('bin')
            else:
                parts.append(w3(q) + ' ' + name)
            n = n % val
    if n:
        parts.append(w3(n))
    return ' '.join(parts)
def fnum(x):
    try:
        return float(x)
    except Exception:
        return 0.0
UNITS = dict(TL=('lira', 'kuruş', 'Türk Lirası'), USD=('dolar', 'sent', 'dolar'), EUR=('euro', 'sent', 'euro'), GBP=('İngiliz sterlini', 'peni', 'İngiliz sterlini'))
CNAME = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
def amount(x, cur):
    x = round(abs(fnum(x)) + 1e-9, 2)
    i = int(x)
    k = int(round((x - i) * 100))
    u = UNITS[cur]
    if k == 0:
        return words(i) + ' ' + u[2]
    if i == 0:
        return words(k) + ' ' + u[1]
    return words(i) + ' ' + u[0] + ' ' + words(k) + ' ' + u[1]
def cop(s):
    last = s.split(' ')[-1]
    m = dict(lira='dır', kuruş='tur', dolar='dır', sent='tir', euro='dur', sterlini='dir', peni='dir')
    if s.endswith('Türk Lirası'):
        return s + "'dır"
    return s + m.get(last, 'dir')
def pdate(s):
    try:
        p = str(s).strip().split('.')
        return datetime.date(int(p[2]), int(p[1]), int(p[0]))
    except Exception:
        return None
def say_date(s):
    d = pdate(s)
    if d is None:
        return str(s or '')
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)
def date_cop(s):
    d = pdate(s)
    if d is None:
        return str(s or '')
    y = d.year
    o = y % 10
    t = (y % 100) // 10
    if o:
        suf = ['', 'dir', 'dir', 'tür', 'tür', 'tir', 'dır', 'dir', 'dir', 'dur'][o]
    elif t:
        suf = ['', 'dur', 'dir', 'dur', 'tır', 'dir', 'tır', 'tir', 'dir', 'dır'][t]
    else:
        suf = 'dür'
    return say_date(s) + "'" + suf
