    raw = str(raw or '').strip()
    for c in cards:
        if raw and (raw.upper() == c.get('code') or raw == c.get('cardNumber')):
            return c
    dg = re.sub(r'\D', '', raw)
    if len(dg) >= 4:
        m = [c for c in cards if c.get('last4') == dg[-4:]]
        if len(m) > 1 and len(dg) >= 10:
            m = [c for c in m if dg.startswith(c.get('first6'))] or m
        if len(m) == 1:
            return m[0]
    return None
def body_ok(result):
    d = result.get('data') if isinstance(result, dict) else None
    if not isinstance(d, dict):
        return False, dict(), dict()
    r = d.get('result') if isinstance(d.get('result'), dict) else dict()
    inner = d.get('data') if isinstance(d.get('data'), dict) else dict()
    ok = str(result.get('status_code')) in ('200', 'None') and str(r.get('returnCode')) == '1'
    return ok, inner, r

try:
    b = config.get('body')
    if isinstance(b, dict):
        c = resolve(vars, b.get('cardNumber'))
        if c is None and str(vars.get('first_card') or '') and vars.get('multi') == 'no':
            c = resolve(vars, vars.get('first_card'))
        if c is not None:
            b['cardNumber'] = c['cardNumber']
            vars['sel_card'] = c['cardNumber']
            vars['sel_name'] = c['name']
            vars['sel_last4'] = c['last4']
            vars['sel_main'] = c['main']
        else:
            b['cardNumber'] = ''
except Exception:
    pass

